mapper.select:
SELECT * FROM ( SELECT NVL((SELECT T.INDENTIFY_MARK FROM CHB_EQU_SUB T WHERE T.ORG_INDENTIFY_MARK = T1.INDENTIFY_MARK AND STATUS !='03' FETCH FIRST 1 ROWS ONLY),T1.INDENTIFY_MARK ) AS indentifyMark, T1.ORG_INDENTIFY_MARK AS orgIndentifyMark, T1.REGIST_BANK_CODE AS bankCode, T1.IS_BELONG_BANK AS isBelongBank, T1.THE_BANK_NAME AS theBankName, T1.THE_BANK_CODE AS theBankCode, T1.HOLDER_MARK AS holderMark, T1.HOLDER_REGION AS holderRegion, T1.HOLDER_TYPE AS holderType, T1.PERSONAL_IDENTIFY_TYPE AS personalIdentifyType, T1.INSTITUTION_IDENTIFY_TYPE AS institutionIdentifyType, T1.OTHER_IDENTIFY_NAME AS otherIdentifyName, T1.IDENTIFY_NUMBER AS identifyNumber, T1.SPV_CAP_ACC_BANK AS spvCapAccBank, T1.OTHER_CAP_ACC_BANK AS otherCapAccBank, T1.SPV_REGIST_CODE AS spvRegistCode, T1.HOLDER_DATE AS holderDate, T1.HOLDER_NAME AS holderName, T1.HOLDER_SEX AS holderSex, T1.HOLDER_RISK_PREFER AS holderRiskPrefer, T1.HOLDER_CELLPHONE AS holderCellphone, T1.HOLDER_TELEPHONE AS holderTelephone, T1.HOLDER_EMAIL AS holderEmail, T1.REMARK AS remark, T1.STATUS AS status, T1.DEPT_CODE AS deptCode, T1.UPDATE_USER AS updateUser, T1.UPDATE_TIME AS updateTime, T1.CREATE_USER AS createUser, T1.ORG_CODE AS orgCode, row_number() OVER(partition by t1.REGIST_BANK_CODE ||'_'||t1.IDENTIFY_NUMBER ||'_'||t1.HOLDER_NAME ||'_'||t1.PERSONAL_IDENTIFY_TYPE ||'_'||t1.INSTITUTION_IDENTIFY_TYPE ||'_'||t1.OTHER_IDENTIFY_NAME order by t1.update_time desc) rank from chb_view_equ_sub T1 inner join CHB_SUBMIT_STATUS t2 on t1.SUMIT_SEQ = t2.SEQNO
t2.SUBMIT_FEEDBACK_STATUS = '03' AND t1.REGIST_BANK_CODE ||'_'||t1.IDENTIFY_NUMBER ||'_'||t1.HOLDER_NAME ||'_'||t1.PERSONAL_IDENTIFY_TYPE ||'_'||t1.INSTITUTION_IDENTIFY_TYPE ||'_'||t1.OTHER_IDENTIFY_NAME = #{key,jdbcType=VARCHAR}
) where rank = 1
